"use client";

import { CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight } from "lucide-react";
import { useEffect, useRef, useState } from "react";

export type ThemedOption = { value: string; label: string };

export function ThemedSelectControl({ value, options, onChange, ariaLabel, compact = false, disabled = false }: { value: string; options: ThemedOption[]; onChange: (value: string) => void; ariaLabel: string; compact?: boolean; disabled?: boolean }) {
  const [open, setOpen] = useState(false); const root = useRef<HTMLDivElement>(null); const selected = options.find((option) => option.value === value);
  useEffect(() => { const close = (event: PointerEvent) => { if (!root.current?.contains(event.target as Node)) setOpen(false); }; document.addEventListener("pointerdown", close); return () => document.removeEventListener("pointerdown", close); }, []);
  return <div ref={root} className={`themed-select vendor-control-select${compact ? " compact" : ""}`}><button type="button" disabled={disabled} className="themed-select-trigger" aria-label={ariaLabel} aria-haspopup="listbox" aria-expanded={open} onClick={() => setOpen((current) => !current)}><span>{selected?.label ?? "Select"}</span><ChevronDown size={16} /></button>{open && !disabled ? <div className="themed-select-menu" role="listbox" aria-label={ariaLabel}>{options.map((option) => <button type="button" role="option" aria-selected={option.value === value} className={option.value === value ? "selected" : ""} key={option.value} onClick={() => { onChange(option.value); setOpen(false); }}><span>{option.label}</span>{option.value === value ? <Check size={15} /> : null}</button>)}</div> : null}</div>;
}

export function ThemedDatePickerControl({ value, minimum, label, onChange }: { value: string; minimum?: string; label: string; onChange: (value: string) => void }) {
  const selected = value ? new Date(`${value}T00:00:00`) : undefined; const [open, setOpen] = useState(false), [month, setMonth] = useState(() => selected ?? new Date()); const root = useRef<HTMLDivElement>(null);
  useEffect(() => { const close = (event: PointerEvent) => { if (!root.current?.contains(event.target as Node)) setOpen(false); }; document.addEventListener("pointerdown", close); return () => document.removeEventListener("pointerdown", close); }, []);
  useEffect(() => { if (selected) setMonth(selected); }, [value]);
  const first = new Date(month.getFullYear(), month.getMonth(), 1), start = new Date(first); start.setDate(first.getDate() - first.getDay()); const days = Array.from({ length: 42 }, (_, index) => { const date = new Date(start); date.setDate(start.getDate() + index); return date; }); const iso = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
  return <div className={`themed-date-control${open ? " open" : ""}`} ref={root}><button type="button" className="themed-date-control-trigger" aria-haspopup="dialog" aria-expanded={open} onClick={() => setOpen((current) => !current)}><span><small>{label}</small><strong>{selected ? selected.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }) : "Select date"}</strong></span><CalendarDays size={17} /></button>{open ? <section className="themed-date-control-calendar" role="dialog" aria-label={`Choose ${label.toLowerCase()}`}><header><button type="button" aria-label="Previous month" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))}><ChevronLeft /></button><strong>{month.toLocaleDateString("en-MY", { month: "long", year: "numeric" })}</strong><button type="button" aria-label="Next month" onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))}><ChevronRight /></button></header><div className="themed-date-weekdays">{["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((day) => <span key={day}>{day}</span>)}</div><div className="themed-date-days">{days.map((day) => { const dayValue = iso(day); return <button type="button" disabled={Boolean(minimum && dayValue < minimum)} className={`${day.getMonth() === month.getMonth() ? "" : "outside"}${dayValue === value ? " selected" : ""}`} key={dayValue} onClick={() => { onChange(dayValue); setOpen(false); }}>{day.getDate()}</button>; })}</div></section> : null}</div>;
}
